164:  *  (lista estatica) vira [min(lista),max(lista)]. */
165: function parseLoadedWeights(indexHtmlPath = INDEX_HTML) {
166:   if (!fs.existsSync(indexHtmlPath)) return {};
167:   const html = fs.readFileSync(indexHtmlPath, 'utf8');
168:   const urlMatch = html.match(/https:\/\/fonts\.googleapis\.com\/css2\?[^"']+/);
169:   if (!urlMatch) return {};
170:   const families = {};
171:   const familyRe = /family=([^&"']+)/g;
172:   let m;
173:   while ((m = familyRe.exec(urlMatch[0]))) {
174:     const [namePart, spec] = m[1].split(':wght@');
175:     const name = decodeURIComponent(namePart.replace(/\+/g, ' '));
176:     if (!spec) { families[name] = [400, 400]; continue; }
177:     const range = spec.match(/^([0-9]+)\.\.([0-9]+)$/);
178:     if (range) {
179:       families[name] = [+range[1], +range[2]];
180:     } else {
181:       const weights = spec.split(';').map(Number).filter((n) => !Number.isNaN(n));
182:       if (weights.length) families[name] = [Math.min(...weights), Math.max(...weights)];
183:     }
184:   }
185:   return families;
186: }
187: 
