192:  *  do eixo publicado da Jakarta (max 800) por limitacao da propria fonte —
193:  *  vira teto no budget, nao zero, ver PR que introduziu a faixa variavel. */
194: function scanOrphanWeights(stylesDir = STYLES, indexHtmlPath = INDEX_HTML) {
195:   const loaded = parseLoadedWeights(indexHtmlPath);
196:   const jakarta = loaded['Plus Jakarta Sans'];
197:   if (!jakarta) return []; // URL ausente/formato mudou — nao quebra o guard por conta disso
198:   const files = ['base.css', 'utilities.css', 'tokens.css']
199:     .map((f) => path.join(stylesDir, f))
200:     .filter((f) => fs.existsSync(f));
201:   const orphan = [];
202:   const re = /font-weight:\s*([0-9]{2,3})\b/g;
203:   for (const f of files) {
204:     const rel = path.relative(ROOT, f);
205:     const txt = fs.readFileSync(f, 'utf8');
206:     let m;
207:     re.lastIndex = 0;
208:     while ((m = re.exec(txt))) {
209:       const w = +m[1];
210:       if (w < jakarta[0] || w > jakarta[1]) {
211:         const line = txt.slice(0, m.index).split('\n').length;
212:         orphan.push({ where: `${rel}:${line}`, weight: w, faixaCarregada: jakarta });
213:       }
214:     }
