1: import { useState, useEffect, useCallback } from 'react';
2: 
3: export type DensityMode = 'comfortable' | 'compact' | 'dense';
4: 
5: const STORAGE_KEY = 'ui-density';
6: 
7: export function useDensity() {
8:   const [density, setDensityState] = useState<DensityMode>(() => {
9:     try {
10:       return (localStorage.getItem(STORAGE_KEY) as DensityMode) || 'comfortable';
11:     } catch {
12:       return 'comfortable';
13:     }
14:   });
15: 
16:   useEffect(() => {
17:     document.documentElement.setAttribute('data-density', density);
18:     try {
19:       localStorage.setItem(STORAGE_KEY, density);
20:     } catch { /* storage unavailable */ }
21:   }, [density]);
22: 
23:   const setDensity = useCallback((mode: DensityMode) => {
24:     setDensityState(mode);
25:   }, []);
26: 
27:   const cycleDensity = useCallback(() => {
28:     setDensityState(prev => {
29:       const order: DensityMode[] = ['comfortable', 'compact', 'dense'];
30:       const idx = order.indexOf(prev);
31:       return order[(idx + 1) % order.length];
32:     });
33:   }, []);
34: 
35:   return { density, setDensity, cycleDensity };

