51: /** Walk a directory and yield .tsx files */
52: function* walkTsx(dir) {
53:   let entries;
54:   try { entries = readdirSync(dir, { withFileTypes: true }); } catch (e) { throw e; }
55:   for (const e of entries) {
56:     const full = path.join(dir, e.name);
57:     if (e.isDirectory()) {
58:       if (e.name === "node_modules" || e.name === ".git") continue;
59:       yield* walkTsx(full);
60:     } else if (e.isFile() && e.name.endsWith(".tsx")) {
61:       yield full;
62:     }
63:   }
64: }
