48: async function checkOverflow(page, url) {
49:   await page.goto(url, { waitUntil: 'networkidle', timeout: 15000 });
50:   // Wait for lazy views to render
51:   await page.waitForTimeout(500);
52: 
53:   // Sem sessao valida a rota cai em /auth e mediriamos a tela de login.
54:   if (new URL(page.url()).pathname.startsWith('/auth')) {
55:     throw new Error('redirecionado para /auth — STORAGE_STATE expirado ou invalido');
56:   }
57: 
58:   const overflow = await page.evaluate(() => {
59:     const docWidth = document.documentElement.scrollWidth;
60:     const vpWidth = window.innerWidth;
61:     if (docWidth <= vpWidth) return null;
62: 
63:     // Find the culprit
64:     const all = document.querySelectorAll('*');
65:     const offenders = [];
66:     for (const el of all) {
67:       const rect = el.getBoundingClientRect();
68:       if (rect.right > vpWidth + 1) {
69:         offenders.push({
70:           tag: el.tagName,
71:           id: el.id || '',
72:           classes: el.className.toString().slice(0, 80),
73:           right: Math.round(rect.right),
74:         });
75:         if (offenders.length >= 5) break;
76:       }
77:     }
78:     return { docWidth, vpWidth, offenders };
79:   });
80: 
81:   return overflow;
82: }
